-- Every new buyer has collected two to four codes ("My coupons").
INSERT INTO promotion_claim (promotion_id, user_id, source, claimed_at)
SELECT p.id, b.user_id, (ARRAY['HOME', 'STORE', 'WALLET_INPUT'])[1 + abs(hashtext(b.username || p.code)) % 3],
       greatest(p.starts_at + interval '1 hour', pg_temp.ago(0.2 + abs(hashtext(p.code || b.username)) % 500 / 100.0))
  FROM seed_new_buyer b
  CROSS JOIN LATERAL (
        SELECT p.* FROM promotion p
         WHERE p.code IN ('MEGA200', 'OPDAY12', 'MTGCMD150', 'PAYDAY300', 'YGO50', 'DIGI8', 'POKEPARA50', 'EEVEEHOU60', 'SEALEDSU70', 'GRADEDGA80', 'STRAWHAT90', 'REDLINET100', 'MANAFORG110', 'COMMANDE120', 'DUELACAD130', 'MILLENNI140', 'DIGIDEST50', 'ANIMEARE60', 'SAIYANCA70', 'CHIANGMA80', 'PHUKETTC90', 'KORATCOL100', 'HATYAIHO110', 'KHONKAEN120', 'BANGNABO130', 'RAREPULL140', 'BUDGETBI50', 'LUMPINIC60', 'MINTVAUL70', 'GRANDLIN80', 'DEMOSELL90', 'PEGASUSO100', 'WELCOME100', 'FREESHIP', 'PEGASUS15')
         ORDER BY md5(b.username || p.code)
         LIMIT 2 + abs(hashtext(b.username || 'promo')) % 3) p;

-- Two older buyers also picked up this month's game codes.
INSERT INTO promotion_claim (promotion_id, user_id, source, claimed_at)
SELECT p.id, pg_temp.uid(v.username), 'HOME', p.starts_at + interval '5 hours'
  FROM (VALUES ('deckbuilder_ton', 'OPDAY12'), ('deckbuilder_ton', 'MTGCMD150'), ('nattapong_tcg', 'MEGA200')) AS v(username, code)
  JOIN promotion p ON p.code = v.code;

UPDATE promotion p
   SET claimed_count = (SELECT count(*) FROM promotion_claim c WHERE c.promotion_id = p.id);
